//! Ownership model for two FPGA SDRAM compressed allocations. No payload lives in ESP32 SRAM.
//! An accepted bus operation stays owned until matching completion, including abort.
use super::framing::crc_extend;
pub const MAX_PACKET:u32=49_152;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Error{Busy,Bounds,Stale,Sequence,Integrity,Outstanding}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum State{Free,Filling,Sealed,Reading,Draining}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct Ticket{pub generation:u64,pub sequence:u32,pub offset:u32,pub length:u32}
#[derive(Debug)]pub struct Slot{state:State,generation:u64,length:u32,completed:u32,crc:u32,next_sequence:u32,pending:Option<Ticket>,read_pending:Option<Ticket>,owner_done:bool,latest_generation:u64}
impl Slot{
 pub const fn new()->Self{Self{state:State::Free,generation:0,length:0,completed:0,crc:!0,next_sequence:0,pending:None,read_pending:None,owner_done:false,latest_generation:0}}
 pub fn state(&self)->State{self.state}
 pub fn begin(&mut self,generation:u64,length:u32)->Result<(),Error>{if self.state!=State::Free{return Err(Error::Busy)}if generation==0||generation<=self.latest_generation{return Err(Error::Stale)}if length==0||length>MAX_PACKET{return Err(Error::Bounds)}self.generation=generation;self.latest_generation=generation;self.length=length;self.completed=0;self.crc=!0;self.next_sequence=0;self.owner_done=false;self.state=State::Filling;Ok(())}
 pub fn accept_write(&mut self,generation:u64,offset:u32,bytes:&[u8])->Result<Ticket,Error>{if generation!=self.generation{return Err(Error::Stale)}if self.state!=State::Filling||self.pending.is_some(){return Err(Error::Busy)}let n=u32::try_from(bytes.len()).map_err(|_|Error::Bounds)?;if n==0||offset!=self.completed||n>self.length-self.completed{return Err(Error::Bounds)}let t=Ticket{generation,sequence:self.next_sequence,offset,length:n};self.next_sequence=self.next_sequence.checked_add(1).ok_or(Error::Sequence)?;self.crc=crc_extend(self.crc,bytes);self.pending=Some(t);Ok(t)}
 pub fn complete_write(&mut self,t:Ticket,ok:bool)->Result<(),Error>{if self.pending!=Some(t){return Err(Error::Stale)}self.pending=None;if !ok{self.state=State::Draining;self.owner_done=true;}else{self.completed+=t.length;}self.recycle();Ok(())}
 pub fn seal(&mut self,generation:u64,expected_crc:u32)->Result<(),Error>{if generation!=self.generation{return Err(Error::Stale)}if self.state!=State::Filling||self.pending.is_some()||self.completed!=self.length{return Err(Error::Outstanding)}if !self.crc!=expected_crc{self.state=State::Draining;self.owner_done=true;self.recycle();return Err(Error::Integrity)}self.state=State::Sealed;Ok(())}
 pub fn acquire(&mut self,generation:u64)->Result<(),Error>{if generation!=self.generation{return Err(Error::Stale)}if self.state!=State::Sealed{return Err(Error::Busy)}self.state=State::Reading;Ok(())}
 pub fn read_accepted(&mut self,generation:u64,offset:u32,length:u32)->Result<Ticket,Error>{if generation!=self.generation{return Err(Error::Stale)}if self.state!=State::Reading||self.read_pending.is_some(){return Err(Error::Busy)}if length==0||offset>=self.length||length>self.length-offset{return Err(Error::Bounds)}let t=Ticket{generation,sequence:self.next_sequence,offset,length};self.next_sequence=self.next_sequence.checked_add(1).ok_or(Error::Sequence)?;self.read_pending=Some(t);Ok(t)}
 pub fn read_completed(&mut self,t:Ticket)->Result<(),Error>{if self.read_pending!=Some(t){return Err(Error::Stale)}self.read_pending=None;self.recycle();Ok(())}
 pub fn owner_done(&mut self,generation:u64)->Result<(),Error>{if generation!=self.generation{return Err(Error::Stale)}self.owner_done=true;self.state=State::Draining;self.recycle();Ok(())}
 fn recycle(&mut self){if self.state==State::Draining&&self.owner_done&&self.pending.is_none()&&self.read_pending.is_none(){self.state=State::Free;}}
}
#[cfg(test)]mod tests{use super::*;use super::super::framing::crc32;
 #[test]fn immutable_until_completion(){let mut s=Slot::new();s.begin(1,3).unwrap();let t=s.accept_write(1,0,b"abc").unwrap();assert_eq!(s.seal(1,crc32(b"abc")),Err(Error::Outstanding));s.complete_write(t,true).unwrap();s.seal(1,crc32(b"abc")).unwrap();assert_eq!(s.accept_write(1,0,b"x"),Err(Error::Busy));s.acquire(1).unwrap();let rt=s.read_accepted(1,0,3).unwrap();s.owner_done(1).unwrap();assert_eq!(s.begin(2,3),Err(Error::Busy));s.read_completed(rt).unwrap();s.begin(2,3).unwrap();assert_eq!(s.complete_write(t,true),Err(Error::Stale));assert_eq!(s.read_completed(rt),Err(Error::Stale));}
 #[test]fn abort_does_not_release_write(){let mut s=Slot::new();s.begin(7,1).unwrap();let t=s.accept_write(7,0,b"x").unwrap();s.owner_done(7).unwrap();assert_eq!(s.state(),State::Draining);s.complete_write(t,true).unwrap();assert_eq!(s.state(),State::Free);assert_eq!(s.begin(7,1),Err(Error::Stale));}
 #[test]fn completion_identity(){let mut s=Slot::new();s.begin(1,2).unwrap();let t=s.accept_write(1,0,b"xy").unwrap();s.complete_write(t,true).unwrap();s.seal(1,crc32(b"xy")).unwrap();s.acquire(1).unwrap();let r=s.read_accepted(1,0,1).unwrap();let wrong=Ticket{offset:1,..r};assert_eq!(s.read_completed(wrong),Err(Error::Stale));s.read_completed(r).unwrap();let r2=s.read_accepted(1,1,1).unwrap();assert_eq!(s.read_completed(r),Err(Error::Stale));s.owner_done(1).unwrap();assert_eq!(s.state(),State::Draining);s.read_completed(r2).unwrap();assert_eq!(s.state(),State::Free);}
 #[test]fn lengths_and_crc(){for n in [0,MAX_PACKET+1,u32::MAX]{assert_eq!(Slot::new().begin(1,n),Err(Error::Bounds));}let mut s=Slot::new();s.begin(1,1).unwrap();let t=s.accept_write(1,0,b"x").unwrap();s.complete_write(t,true).unwrap();assert_eq!(s.seal(1,0),Err(Error::Integrity));assert_eq!(s.state(),State::Free);}
}
